<script setup lang="ts">
import type { UserAction } from '../../../../views/user-types.d.ts'

import { mdiPencilOutline } from '@mdi/js'
import { t } from '@nextcloud/l10n'
import isSvg from 'is-svg'
import { computed } from 'vue'
import NcActionButton from '@nextcloud/vue/components/NcActionButton'
import NcActions from '@nextcloud/vue/components/NcActions'
import NcIconSvgWrapper from '@nextcloud/vue/components/NcIconSvgWrapper'

const props = defineProps<{
	/** Actions of the menu */
	actions: readonly UserAction[]
	/** Disable the actions, e.g. while the row is saving */
	disabled: boolean
	/** The account the actions run for */
	user: Record<string, unknown>
}>()

defineEmits<{
	/** The edit dialog should open */
	'update:edit': [value: boolean]
}>()

const enabledActions = computed<UserAction[]>(() => props.actions.filter((action) => typeof action.enabled === 'function' ? action.enabled(props.user) : true))
</script>

<template>
	<NcActions
		:aria-label="t('settings', 'Toggle account actions menu')"
		:disabled="disabled"
		:inline="1">
		<NcActionButton
			data-cy-user-list-action-edit
			:disabled="disabled"
			@click="$emit('update:edit', true)">
			{{ t('settings', 'Edit') }}
			<template #icon>
				<NcIconSvgWrapper :path="mdiPencilOutline" />
			</template>
		</NcActionButton>
		<NcActionButton
			v-for="({ action, icon, text }, index) in enabledActions"
			:key="index"
			:disabled="disabled"
			:aria-label="text"
			:icon="icon"
			closeAfterClick
			@click="(event) => action(event, { ...user })">
			{{ text }}
			<template v-if="isSvg(icon)" #icon>
				<NcIconSvgWrapper :svg="icon" aria-hidden="true" />
			</template>
		</NcActionButton>
	</NcActions>
</template>
